mapper.select:
select
con.Con_Name as conName, c1.C_Name as dccsMainUnitName, mn.* from Con_Dccs mn left join Sys_Company c1 on c1.C_Id = mn.Dccs_Main_Unit
left join Con_Contract con on con.Con_Id=mn.Con_Id where mn.Dccs_Id = #{id}

select

con.Con_Name as conName,
c1.C_Name as dccsMainUnitName,
mn.*
from Con_Dccs mn
left join Sys_Company c1 on c1.C_Id = mn.Dccs_Main_Unit

left join Con_Contract con on con.Con_Id=mn.Con_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.State=#{params.state}


    and mn.P_Id=#{params.pId}


    
        
            and likeCname(#{params.dccsMainUnitName},c1.C_Id)=true
        
        
            and INSTR(c1.C_Name,#{params.dccsMainUnitName})
        
    


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and INSTR(pro.P_Name,#{params.pName})
        
    


    and INSTR(mn.Create_Uname,#{params.createUname})


    and INSTR(con.Con_Name,#{params.conName})


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
